"use strict";

module.exports = function eventsProbe() {
  const events = require("events");
  const emitter = new events.EventEmitter();
  const ready = events.once(emitter, "ready").then((args) => {
    return {
      ok:
        args[0] === "ready" &&
        emitter.listenerCount("ready") === 0 &&
        typeof events.EventTarget === "undefined" &&
        typeof globalThis.EventTarget === "function",
      summary: "events:" + args[0] + "/" + emitter.listenerCount("ready"),
    };
  });
  process.nextTick(() => {
    emitter.emit("ready", "ready");
  });
  return ready;
};
